css:
#tongsci1-3-3-1-factory .fc-body { grid-template-columns: 1080px minmax(0, 1fr); }
#tongsci1-3-3-1-factory .fc-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #e6f1f2; }
#tongsci1-3-3-1-factory .fc-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-1-factory .fc-panel { gap: 10px; }
#tongsci1-3-3-1-factory .fc-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
#tongsci1-3-3-1-factory .fc-out b { color: var(--accent); }
#tongsci1-3-3-1-factory .fc-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 16px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-1-factory .fc-tab th { font: 700 16px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-1-factory .fc-tab th:nth-child(1) { width: 25%; }
#tongsci1-3-3-1-factory .fc-tab th:nth-child(4) { width: 13%; }
#tongsci1-3-3-1-factory .fc-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 5px; height: 40px; color: var(--ink-3); }
#tongsci1-3-3-1-factory .fc-tab td:first-child { font-weight: 800; text-align: center; }
#tongsci1-3-3-1-factory .fc-tab td:last-child { text-align: center; }
#tongsci1-3-3-1-factory .fc-tab tr.ok td { color: var(--ink); }
#tongsci1-3-3-1-factory .fc-tab tr.ok td:first-child { color: var(--good); }
#tongsci1-3-3-1-factory .fc-note { margin: 0; font-size: 18px; line-height: 1.45; color: var(--ink-2); flex: none; }
section#tongsci1-3-3-1-factory.ex.u-done .fc-note { display: none; }

